"""Pure deterministic policy; caller supplies authoritative episode-local metadata."""

from agentguard.contracts import (
    Action,
    Decision,
    Document,
    ListAction,
    Profile,
    Project,
    ReadAction,
    SearchAction,
    ShareAction,
    TaskContract,
    Ticket,
    UpdateAction,
    digest,
)

POLICY_VERSION = "gateway-v2"


def evaluate(
    *,
    episode_id: str,
    contract: TaskContract,
    profile: Profile,
    action: Action,
    resource: Document | Project | None,
    confidential: bool,
    ticket: Ticket | None = None,
    source: Document | None = None,
    collection: tuple[Document | Ticket, ...] = (),
) -> Decision:
    action_hash = digest(
        {
            "episode_id": episode_id,
            "contract": contract.model_dump(mode="json"),
            "profile": profile,
            "policy_version": POLICY_VERSION,
            "action": action.model_dump(mode="json"),
            "resource": resource.model_dump(mode="json") if resource else None,
            "confidential": confidential,
            "ticket": ticket.model_dump(mode="json") if ticket else None,
            "source": source.model_dump(mode="json") if source else None,
            "collection": [item.model_dump(mode="json") for item in collection],
        }
    )

    def decision(outcome: str, reason: str) -> Decision:
        return Decision.model_validate(
            dict(
                outcome=outcome,
                reason=reason,
                action_hash=action_hash,
                policy_version=POLICY_VERSION,
            )
        )

    # Outer resource identity and optimistic concurrency apply to every profile.
    if not isinstance(action, SearchAction):
        target = (
            action.arguments.document_id
            if isinstance(action, ReadAction)
            else action.arguments.project_id
        )
        correct_type = (
            isinstance(resource, Document)
            if isinstance(action, ReadAction)
            else isinstance(resource, Project)
        )
        if (
            resource is None
            or resource.workspace != contract.workspace
            or resource.id != target
            or not correct_type
        ):
            return decision("DENY", "RESOURCE_UNAVAILABLE")
    if isinstance(action, UpdateAction) and (
        ticket is None
        or ticket.workspace != contract.workspace
        or ticket.id != action.arguments.ticket_id
        or ticket.project_id != action.arguments.project_id
    ):
        return decision("DENY", "RESOURCE_UNAVAILABLE")
    if isinstance(action, ShareAction) and (
        source is None
        or source.workspace != contract.workspace
        or source.id != action.arguments.document_id
    ):
        return decision("DENY", "RESOURCE_UNAVAILABLE")
    if any(item.workspace != contract.workspace for item in collection):
        return decision("DENY", "RESOURCE_UNAVAILABLE")
    if profile not in ("baseline", "prompt_only", "defended"):
        return decision("DENY", "UNKNOWN_PROFILE")
    if profile == "defended":
        if action.tool not in contract.allowed_tools:
            return decision("DENY", "ACTION_OUT_OF_SCOPE")
        if isinstance(action, SearchAction):
            if any(
                not isinstance(d, Document)
                or d.id not in contract.document_ids
                or contract.actor not in d.readers
                for d in collection
            ):
                return decision("DENY", "RESOURCE_UNAVAILABLE")
        elif isinstance(action, ReadAction):
            assert isinstance(resource, Document)
            if resource.id not in contract.document_ids:
                return decision("DENY", "RESOURCE_OUT_OF_SCOPE")
            if contract.actor not in resource.readers:
                return decision("DENY", "ACTOR_FORBIDDEN")
        else:
            assert isinstance(resource, Project)
            if resource.id not in contract.project_ids:
                return decision("DENY", "RESOURCE_OUT_OF_SCOPE")
            readers = (*resource.readers, *resource.writers)
            permitted = readers if isinstance(action, ListAction) else resource.writers
            if contract.actor not in permitted:
                return decision("DENY", "ACTOR_FORBIDDEN")
            if isinstance(action, ShareAction):
                assert source is not None
                if source.id not in contract.document_ids:
                    return decision("DENY", "RESOURCE_OUT_OF_SCOPE")
                if contract.actor not in source.readers:
                    return decision("DENY", "ACTOR_FORBIDDEN")
            if not isinstance(action, ListAction):
                sensitive = (
                    confidential
                    or (ticket is not None and ticket.classification == "confidential")
                    or (source is not None and source.classification == "confidential")
                )
                if sensitive and resource.visibility == "shared":
                    return decision("DENY", "CONFIDENTIAL_TO_SHARED")
                if isinstance(action, UpdateAction):
                    assert ticket is not None
                    if ticket.version != action.arguments.expected_version:
                        return decision("DENY", "VERSION_CONFLICT")
                if sensitive or resource.visibility == "shared" or isinstance(action, ShareAction):
                    return decision("REQUIRE_APPROVAL", "SENSITIVE_WRITE")
    if isinstance(action, UpdateAction):
        assert ticket is not None
        if ticket.version != action.arguments.expected_version:
            return decision("DENY", "VERSION_CONFLICT")
    return decision(
        "ALLOW",
        "AUTHORIZED" if profile == "defended" else "EXPERIMENTAL_BUSINESS_CONTROLS_DISABLED",
    )

tool_state.py:
"""Resolve authoritative resources within a transaction, before tool computation."""

import sqlite3
from dataclasses import dataclass

from agentguard.computation import DocumentSnapshot, SearchHit, TicketPreview, ToolRequest
from agentguard.contracts import (
    Action,
    Decision,
    Document,
    ListAction,
    Profile,
    Project,
    ReadAction,
    SearchAction,
    ShareAction,
    TaskContract,
    Ticket,
    UpdateAction,
)
from agentguard.policy import evaluate


def preview(text: str) -> str:
    return text.encode("utf-8")[:512].decode("utf-8", errors="ignore")


@dataclass(frozen=True)
class ToolState:
    resource: Document | Project | None = None
    ticket: Ticket | None = None
    source: Document | None = None
    collection: tuple[Document | Ticket, ...] = ()
    hits: tuple[SearchHit, ...] = ()

    def decision(
        self,
        *,
        episode_id: str,
        contract: TaskContract,
        profile: Profile,
        action: Action,
        confidential: bool,
    ) -> Decision:
        return evaluate(
            episode_id=episode_id,
            contract=contract,
            profile=profile,
            action=action,
            confidential=confidential,
            resource=self.resource,
            ticket=self.ticket,
            source=self.source,
            collection=self.collection,
        )

    def request(self, action: Action) -> ToolRequest:
        document = self.resource if isinstance(action, ReadAction) else self.source
        return ToolRequest(
            action=action,
            document=DocumentSnapshot(id=document.id, body=document.body)
            if isinstance(document, Document)
            else None,
            documents=self.hits,
            tickets=tuple(
                TicketPreview(
                    ticket_id=t.id,
                    project_id=t.project_id,
                    title=t.title,
                    body_preview=preview(t.body),
                    version=t.version,
                )
                for t in self.collection
                if isinstance(t, Ticket)
            ),
        )

    @property
    def sensitive(self) -> bool:
        resources = (self.resource, self.source, self.ticket, *self.collection)
        return any(
            isinstance(r, (Document, Ticket)) and r.classification == "confidential"
            for r in resources
        )


def resolve(
    db: sqlite3.Connection, episode: str, contract: TaskContract, profile: Profile, action: Action
) -> ToolState:
    def document(identifier: str) -> Document | None:
        row = db.execute(
            "SELECT payload FROM resources WHERE episode_id=? AND kind='document' AND id=?",
            (episode, identifier),
        ).fetchone()
        return Document.model_validate_json(row[0]) if row else None

    if isinstance(action, SearchAction):
        # Quote the complete user query as an FTS phrase: no operators, column selectors,
        # or SQL syntax are accepted. Stable ID ordering never exposes global FTS ranks.
        query = '"' + action.arguments.query.replace('"', '""') + '"'
        rows = db.execute(
            "SELECT r.payload, snippet(documents_fts, 2, '', '', ' … ', 24) AS excerpt "
            "FROM documents_fts JOIN resources r ON r.rowid=documents_fts.rowid "
            "WHERE documents_fts MATCH ? AND r.episode_id=? AND r.kind='document' "
            "ORDER BY r.id",
            (query, episode),
        )
        documents, hits = [], []
        for row in rows:
            doc = Document.model_validate_json(row["payload"])
            if doc.workspace != contract.workspace or (
                profile == "defended"
                and (doc.id not in contract.document_ids or contract.actor not in doc.readers)
            ):
                continue
            documents.append(doc)
            hits.append(
                SearchHit(document_id=doc.id, snippet=preview(row["excerpt"]), version=doc.version)
            )
            if len(hits) == action.arguments.limit:
                break
        return ToolState(collection=tuple(documents), hits=tuple(hits))
    if isinstance(action, ReadAction):
        return ToolState(resource=document(action.arguments.document_id))
    row = db.execute(
        "SELECT payload FROM resources WHERE episode_id=? AND kind='project' AND id=?",
        (episode, action.arguments.project_id),
    ).fetchone()
    project = Project.model_validate_json(row[0]) if row else None
    if isinstance(action, ShareAction):
        return ToolState(resource=project, source=document(action.arguments.document_id))
    if isinstance(action, UpdateAction):
        row = db.execute(
            "SELECT * FROM tickets WHERE episode_id=? AND id=?",
            (episode, action.arguments.ticket_id),
        ).fetchone()
        ticket = Ticket.model_validate({k: row[k] for k in Ticket.model_fields}) if row else None
        return ToolState(resource=project, ticket=ticket)
    if isinstance(action, ListAction):
        rows = db.execute(
            "SELECT * FROM tickets WHERE episode_id=? AND project_id=? "
            "AND workspace=? ORDER BY id LIMIT ?",
            (episode, action.arguments.project_id, contract.workspace, action.arguments.limit),
        )
        return ToolState(
            resource=project,
            collection=tuple(
                Ticket.model_validate({k: row[k] for k in Ticket.model_fields}) for row in rows
            ),
        )
    return ToolState(resource=project)
